-- Call Lab (MP-442, 2026-09-06): AI voice role-play and call certification, built INTO the site.
-- Three tables, no new RPCs: scenarios (versioned content as JSON), sessions (one row per call,
-- brain state + frozen scenario snapshot + scorecard), events (append-only, idempotent).
-- Agents own their sessions/events; admins and managers read the organization's.

create table if not exists public.call_lab_scenarios (
  id text primary key,
  version integer not null default 1,
  title text not null,
  data jsonb not null,
  persona jsonb not null,
  objections jsonb not null,
  rubric jsonb not null,
  claims jsonb not null,
  difficulty smallint not null default 2 check (difficulty between 1 and 3),
  is_active boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table public.call_lab_scenarios enable row level security;
drop policy if exists call_lab_scenarios_read on public.call_lab_scenarios;
create policy call_lab_scenarios_read on public.call_lab_scenarios for select to authenticated using (is_active or public.apex_is_admin());
drop policy if exists call_lab_scenarios_admin_write on public.call_lab_scenarios;
create policy call_lab_scenarios_admin_write on public.call_lab_scenarios for all to authenticated using (public.apex_is_admin()) with check (public.apex_is_admin());

create table if not exists public.call_lab_sessions (
  id text primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  scenario_id text not null references public.call_lab_scenarios(id),
  scenario_version integer not null,
  scenario_snapshot jsonb not null,          -- frozen title/persona/objections/rubric/claims at start
  mode text not null default 'practice' check (mode in ('practice','coach')),
  provider text not null default 'composed' check (provider in ('demo','composed')),
  tts text not null default 'browser' check (tts in ('browser','elevenlabs')),
  focus_objection_id text,
  status text not null default 'created' check (status in ('created','live','ending','evaluating','complete','failed')),
  brain_state jsonb,
  audio jsonb,                               -- level aggregates per speaker (never audio)
  started_at timestamptz,
  ended_at timestamptz,
  end_reason text,
  duration_ms integer,
  scorecard jsonb,                           -- frozen result; manager override lives beside it in scorecard.override
  evaluator text,
  eval_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists call_lab_sessions_user_idx on public.call_lab_sessions (user_id, created_at desc);
alter table public.call_lab_sessions enable row level security;
drop policy if exists call_lab_sessions_own on public.call_lab_sessions;
create policy call_lab_sessions_own on public.call_lab_sessions for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists call_lab_sessions_staff_read on public.call_lab_sessions;
create policy call_lab_sessions_staff_read on public.call_lab_sessions for select to authenticated using (public.apex_is_admin() or public.apex_has_any_role(array['manager']));

create table if not exists public.call_lab_events (
  session_id text not null references public.call_lab_sessions(id) on delete cascade,
  event_id text not null,
  type text not null,
  at_ms integer not null,
  payload jsonb not null,
  created_at timestamptz not null default now(),
  primary key (session_id, event_id)
);
create index if not exists call_lab_events_session_at_idx on public.call_lab_events (session_id, at_ms);
alter table public.call_lab_events enable row level security;
drop policy if exists call_lab_events_own on public.call_lab_events;
create policy call_lab_events_own on public.call_lab_events for all to authenticated
  using (exists (select 1 from public.call_lab_sessions s where s.id = session_id and s.user_id = auth.uid()))
  with check (exists (select 1 from public.call_lab_sessions s where s.id = session_id and s.user_id = auth.uid()));
drop policy if exists call_lab_events_staff_read on public.call_lab_events;
create policy call_lab_events_staff_read on public.call_lab_events for select to authenticated using (public.apex_is_admin() or public.apex_has_any_role(array['manager']));

grant select, insert, update on public.call_lab_sessions to authenticated;
grant select, insert on public.call_lab_events to authenticated;
grant select, insert, update, delete on public.call_lab_scenarios to authenticated;

-- Seed: the agency's real veteran final-expense scenarios (script lives in sales_scripts already).
insert into public.call_lab_scenarios (id, title, data, persona, objections, rubric, claims, difficulty, is_active) values
  ('vet-fe-verification', '"Veteran Final Expense — Verification Call"', '{"difficulty": 2, "segment": "Final expense · veterans", "skills": ["discovery", "objection handling", "closing"], "estimatedMinutes": 8, "maxDurationSec": 900, "goal": "Verify the veteran''s burial coverage status, run the needs analysis, present coverage and earn a commitment to start the draft.", "agentGoal": "get the prospect to choose a coverage amount within budget and agree to set up the monthly draft today", "prospectGoal": "protect a fixed income, avoid being scammed, and not commit without understanding what is being bought", "winCondition": "A specific monthly amount is agreed and the prospect commits to the next step (bank draft now, or a scheduled joint call with the spouse).", "difficultyPolicy": "Standard: the prospect answers direct questions honestly but volunteers nothing; one clarifying question is usually enough to unlock context; objections are stated once and re-raised only if handled weakly.", "earlyEndConditions": ["Prospect hangs up after the agent implies VA or government affiliation (critical failure).", "Prospect ends the call if the agent talks for more than 60 seconds without a question, twice."], "allowedReferenceMaterial": ["Veteran Final Expense — Full Call Script", "Objection library"], "gradedSummary": ["Discovery before pitching", "Handling of the three required objections", "Accuracy of every claim", "A concrete next step"], "openingLine": "Hello? Who''s this?"}', '{"name": "Walter Reyes", "role": "Retired Army staff sergeant, 71", "companyProfile": "Household of two on Social Security and a small Army pension in Mesa, Arizona", "situation": "Received several ''veteran benefits'' calls this year and hung up on most of them; his wife Linda handles the bills.", "currentSolution": "A $10,000 group policy from a former employer that he believes is still active; unsure whether it ended at retirement.", "businessPressure": "Fixed income; a recent hospital bill for Linda made him aware of what costs land on the family.", "decisionProcess": "Decides jointly with Linda; will not give bank details on a first call unless the caller is clearly legitimate.", "knowledgeLevel": "Knows the VA burial allowance exists but not what it pays; does not know term vs whole life.", "speakingStyle": "Short sentences, dry humor, suspicious at first, warms up when treated straight; says ''go ahead'' when convinced.", "hiddenPriorities": ["Not leaving Linda with a bill", "Not being fooled", "Keeping the payment under about $60 a month"], "hardConstraints": ["Will not proceed if the caller implies the VA or government is involved", "Will not give bank details before identity and licensing are stated"], "age": 71, "voice": {"provider": "elevenlabs", "voiceId": "pqHfZKP75CvOlQylNhV4", "label": "Bill — older American male", "pitchHint": "low"}}', '[{"id": "trust_scam", "key": "trust_scam", "required": true, "title": "How do I know this isn''t a scam?", "data": {"difficulty": 2, "intent": "Prospect questions the caller''s legitimacy and the authority behind the call.", "underlyingConcern": "Has received fraudulent ''benefits'' calls before; needs verifiable identity and a reason to keep listening.", "canonicalForms": ["How do I know you''re legitimate?", "I get scam calls every day.", "Who are you with again?"], "variations": ["My son told me never to give information over the phone.", "Is this the VA calling?"], "triggers": {"afterPhase": "open", "minAgentTurns": 1, "keywords": ["verify", "benefits", "coordinator"]}, "responsePrinciples": ["State the agency name, the agent''s name and license status plainly.", "Never imply government or VA affiliation.", "Offer a verifiable step (callback number, carrier name, written confirmation) and keep the call moving."], "disallowedClaims": ["We are calling from the VA", "This is a government program", "You were selected by the military"], "evidenceRefs": ["script:GAIN CREDENTIALS", "brand:Apex Standard"], "resolutionChecks": ["Prospect accepts the identity explanation and continues answering questions."], "followUps": {"ifWeak": ["That doesn''t tell me anything. Which company?"], "ifStrong": ["Alright, go ahead then."]}, "example": "I''m a licensed life insurance agent with the agency, not the VA — the VA doesn''t call about this. Here''s my license number and a callback line; the coverage itself is written by an A-rated carrier.", "category": "trust_risk"}}, {"id": "price_cant_afford", "key": "price_cant_afford", "required": true, "title": "I can''t afford it", "data": {"difficulty": 2, "intent": "Prospect frames the monthly premium as unaffordable on a fixed income.", "underlyingConcern": "Fear of a payment that competes with rent, medication or groceries; wants the agent to right-size instead of upsell.", "canonicalForms": ["I can''t afford that right now.", "That''s too much money every month.", "I''m on a fixed income, I can''t add a bill."], "variations": ["Money is tight, I don''t know about adding another payment.", "My Social Security check doesn''t stretch that far.", "That''s more than I was thinking."], "triggers": {"afterPhase": "positioning", "minAgentTurns": 4, "keywords": ["month", "premium", "$", "dollars", "per month"]}, "responsePrinciples": ["Acknowledge the budget concern without retreating from the need.", "Re-anchor on what happens to the family with no coverage.", "Right-size the premium to the stated comfort level; the coverage can increase later.", "Offer two concrete price points instead of an open question."], "disallowedClaims": ["Rates are locked forever regardless of carrier", "The plan is free or paid for by the VA", "Approval is guaranteed"], "evidenceRefs": ["script:IF PRICE TOO HIGH", "library:Objection — I can''t afford it"], "resolutionChecks": ["Prospect names or accepts a monthly amount.", "Agent confirms the amount is comfortable before moving on."], "followUps": {"ifWeak": ["I hear you, but I still don''t see where the money comes from.", "Can you just send me something in the mail?"], "ifStrong": ["Fifty a month I could probably do.", "If it''s around that, okay."]}, "example": "I hear you — I''m not here to put you in something you can''t afford. That''s why I asked about your budget upfront.\n\nQuestion though: what happens to your family if something happens to you and there''s NO coverage? That''s the real ''can''t afford it.''\n\nLet''s start at the level you''re comfortable with — we can always increase later. What works — $50/mo or $100/mo?", "category": "price_budget"}}, {"id": "spouse_decision", "key": "spouse_decision", "required": true, "title": "I need to talk to my spouse", "data": {"difficulty": 2, "intent": "Prospect defers the decision to a spouse who is not on the call.", "underlyingConcern": "Does not want to commit to a household expense alone; may also be using the spouse as a polite exit.", "canonicalForms": ["I need to talk to my wife first.", "My husband handles this kind of thing.", "I can''t decide without my spouse."], "variations": ["Let me run it by Linda and call you back.", "We make these decisions together."], "triggers": {"afterPhase": "close", "minAgentTurns": 6, "keywords": ["lock in", "set up", "bank", "draft", "today"]}, "responsePrinciples": ["Validate that the decision affects the spouse.", "Ask what the spouse would say about leaving the family unprotected.", "Offer to include the spouse now or lock the rate with the free-look period as the safety net.", "Confirm the plan and next step explicitly."], "disallowedClaims": ["The spouse cannot cancel", "There is no free-look or cancellation period"], "evidenceRefs": ["library:Objection — I need to talk to my spouse"], "resolutionChecks": ["Prospect agrees to proceed now, or a concrete joint call time is set with both parties.", "Agent states the free-look terms accurately."], "followUps": {"ifWeak": ["She''s going to say no, I already know it.", "Just mail me the paperwork."], "ifStrong": ["Well, if I can cancel within thirty days I suppose that''s fair.", "Let me grab her, she''s in the kitchen."]}, "example": "I totally get that — this IS a decision that affects them. Quick question: if you came home tonight and said you DIDN''T protect them, what do you think they''d say?\n\nLet''s do this: I''ll lock in the rate at today''s health, you have 30 days to cancel for any reason — including if your spouse says no — and you''ll have peace of mind tonight knowing it''s done. Sound fair?", "category": "authority_decision"}}, {"id": "think_about_it", "key": "think_about_it", "required": false, "title": "I need to think about it", "data": {"difficulty": 1, "intent": "Generic stall with no specific concern named.", "underlyingConcern": "An unspoken concern (price, trust, or carrier) that the prospect has not articulated; wants time to consult or to end the call politely.", "canonicalForms": ["Let me think about it.", "I''m not going to decide today.", "Call me back next week."], "variations": ["I want to sleep on it.", "I don''t like making decisions on the phone."], "triggers": {"afterPhase": "close", "minAgentTurns": 5}, "responsePrinciples": ["Isolate the real concern: price, coverage amount, or carrier.", "Explain the cost of waiting in factual terms (age-banded rates, health changes).", "Do not pressure; make deciding now easier than deciding later."], "disallowedClaims": ["Rates go up tomorrow", "This offer expires tonight"], "evidenceRefs": ["library:Objection — I need to think about it"], "resolutionChecks": ["The specific concern is named by the prospect.", "Agent addresses that concern and re-asks for the decision."], "followUps": {"ifWeak": ["I just need time, that''s all."], "ifStrong": ["I guess it''s mostly the price I''m unsure about."]}, "example": "Of course — this is your family''s protection, not a small decision. Help me understand what specifically you need to think about — the price, the coverage amount, or the carrier?\n\nBecause whatever it is, I''d rather we figure it out together right now than have you sit on it for a month while your rate goes up.", "category": "timing_priority"}}, {"id": "existing_coverage", "key": "existing_coverage", "required": false, "title": "I already have coverage", "data": {"difficulty": 2, "intent": "Prospect believes an existing policy or the VA burial benefit already covers the need.", "underlyingConcern": "Does not want to duplicate a cost; may not know what the existing coverage actually pays or whether it is term coverage that will expire.", "canonicalForms": ["I already have life insurance.", "The VA covers my burial.", "I have something through my old job."], "variations": ["My wife has a policy on me already.", "Don''t veterans get a burial paid for?"], "triggers": {"afterPhase": "discovery", "minAgentTurns": 3, "keywords": ["coverage", "policy", "burial"]}, "responsePrinciples": ["Ask what the existing coverage pays and when it ends.", "Explain the difference between a term policy, a work policy that ends at retirement, and permanent final-expense coverage.", "Position the new coverage as filling the gap, not replacing what works."], "disallowedClaims": ["The VA pays nothing toward burial", "Your existing policy is worthless"], "evidenceRefs": ["script:TERM CONVERSION PITCH", "script:FINAL EXPENSE INFLATION PITCH"], "resolutionChecks": ["Prospect states what the existing coverage pays.", "Agent quantifies the gap and the prospect acknowledges it."], "followUps": {"ifWeak": ["I think it''s enough, honestly."], "ifStrong": ["I''m not sure how much it pays, to be honest."]}, "example": "That''s good — let''s make sure it does what you think. Is that a term policy or something that lasts your whole life, and do you know the amount? Most work policies end at retirement, and the VA burial allowance is a partial reimbursement, not a payout.", "category": "need_status_quo"}}, {"id": "healthy_not_now", "key": "healthy_not_now", "required": false, "title": "I''m healthy, I don''t need this now", "data": {"difficulty": 3, "intent": "Prospect sees no urgency because of current good health.", "underlyingConcern": "Discomfort with mortality; wants a reason grounded in facts rather than fear.", "canonicalForms": ["I''m in great shape, this can wait.", "I''ll deal with it when I''m older.", "Nobody in my family goes early."], "variations": ["My doctor says I''m fine.", "I''m not planning on going anywhere."], "triggers": {"afterPhase": "positioning", "minAgentTurns": 4, "keywords": ["health", "qualify", "rate"]}, "responsePrinciples": ["Agree that good health is exactly why now is the right time (rates are set at today''s age and health).", "Use factual age-banded pricing, not fear.", "Tie back to the beneficiary the prospect named earlier."], "disallowedClaims": ["You will not qualify later", "Guaranteed acceptance at any age"], "evidenceRefs": ["script:DEEP DIVE", "script:IF THEY HESITATE"], "resolutionChecks": ["Prospect accepts that locking today''s health class is the reason to act now."], "followUps": {"ifWeak": ["I hear that from every salesman."], "ifStrong": ["I suppose it''s cheaper now than later."]}, "example": "That''s exactly why we''re talking now — the rate is set by your age and health today, and it never goes up. If we wait until something changes, the same coverage costs more or isn''t available. And you told me Linda would be the one handling everything.", "category": "timing_priority"}}]', '{"dimensions": [{"id": "discovery", "label": "Discovery and diagnosis", "points": 15, "description": "Relevant questions, depth, sequencing, and use of answers.", "excellent": "Asks who the coverage is for and why, uncovers the budget and health picture, and uses each answer in the next question."}, {"id": "objection_recognition", "label": "Objection recognition", "points": 10, "description": "Identifies the real concern rather than answering the surface phrase.", "excellent": "Names the concern under the words (''it sounds like the worry is the monthly bill, not the coverage'') before responding."}, {"id": "acknowledge_clarify", "label": "Acknowledge and clarify", "points": 15, "description": "Validates without capitulating; asks focused clarifying questions.", "excellent": "One sentence of acknowledgement, then a specific clarifying question, then silence."}, {"id": "response_accuracy", "label": "Response relevance and accuracy", "points": 15, "description": "Direct, tailored, script- and claim-grounded response without fabrication.", "excellent": "Uses only approved facts, ties the response to what the prospect said, and never invents a rate or guarantee."}, {"id": "resolution_advancement", "label": "Resolution and advancement", "points": 15, "description": "Checks resolution, earns commitment, and advances to a credible next step.", "excellent": "Asks ''does that take care of it?'', hears a yes, and moves to the concrete next step."}, {"id": "listening_control", "label": "Listening and call control", "points": 10, "description": "Turn balance, interruptions, concise transitions, agenda and time control.", "excellent": "Lets the prospect finish, keeps turns short, and steers back to the agenda without talking over them."}, {"id": "value_articulation", "label": "Value articulation", "points": 10, "description": "Connects value to stated priorities with appropriate proof.", "excellent": "Repeats the prospect''s own reason back and attaches the coverage to it."}, {"id": "delivery", "label": "Delivery and tonality", "points": 5, "description": "Observable pace, clarity, fillers, pauses, and volume consistency.", "excellent": "Steady pace inside the benchmark, few fillers, deliberate pauses after questions."}, {"id": "compliance", "label": "Compliance and professionalism", "points": 5, "description": "Required disclosures, approved claims, respectful conduct, data handling.", "excellent": "States identity and licensing plainly, never implies VA or government affiliation, handles bank details only after consent."}], "objectionStages": {"acknowledge": 15, "clarify": 20, "isolate": 15, "respond": 25, "proof": 10, "confirm": 15}, "passRules": {"overallMin": 80, "requiredObjectionMin": 70, "complianceMin": 4, "complianceCriterionId": "compliance", "evidenceCoverageMin": 0.6}, "criticalFailureRules": [{"id": "fabricated_fact", "label": "Fabricated price, guarantee, legal term, or capability", "description": "Any specific rate, guarantee, approval promise, legal term or carrier capability not present in approved knowledge."}, {"id": "government_affiliation", "label": "Implied VA or government affiliation", "description": "Stating or implying the call is from the VA, the military, or a government program."}, {"id": "prohibited_language", "label": "Prohibited, discriminatory, coercive or abusive language", "description": "Threats, slurs, or coercion of any kind."}, {"id": "missing_disclosure", "label": "Missing mandatory disclosure", "description": "Bank or payment details requested before identity, agency and licensing were stated."}, {"id": "sensitive_data", "label": "Mishandling sensitive data", "description": "Reading back or repeating full bank, Social Security or card numbers aloud."}, {"id": "unauthorized_commitment", "label": "Unapproved commitment on behalf of the company", "description": "Promising refunds, rate holds or approvals the agency cannot make."}], "deliveryBenchmarks": {"wordsPerMinute": [130, 175], "fillersPerMinute": 4, "longestMonologueSec": 45, "talkRatioAgent": [0.4, 0.6], "responseLatencyMs": [300, 1800]}}', '{"approved": [{"text": "Coverage is written by an A-rated carrier and the rate is set by your age and health at the time you apply.", "category": "pricing", "source": "script:DEEP DIVE"}, {"text": "Once the policy is in force, the premium does not increase and the coverage does not decrease.", "category": "product", "source": "script:FINAL EXPENSE INFLATION PITCH"}, {"text": "There is a free-look period after the policy is issued during which it can be cancelled for a full refund (30 days is the figure in the agency library; state minimums vary).", "category": "terms", "source": "library:Objection — I need to talk to my spouse"}, {"text": "The agent is a licensed life insurance agent with the agency; the agency is not the VA and does not represent any government program.", "category": "identity", "source": "brand:Apex Standard"}, {"text": "Coverage can start at a lower amount and be increased later, subject to underwriting.", "category": "product", "source": "library:Objection — I can''t afford it"}, {"text": "The beneficiary receives the death benefit directly and can use it for any purpose, including burial costs.", "category": "product", "source": "script:BENEFICIARY"}], "prohibited": [{"text": "Implying the call is from the VA, the military, or a government program", "reason": "Deceptive; also a compliance violation", "severity": "critical", "patterns": ["calling from the va", "this is the va", "government program", "government benefit", "military benefit", "with the va", "va benefits office", "the va benefits", "government burial benefit", "your government benefit", "from the veterans administration"]}, {"text": "Guaranteeing approval or a specific rate before underwriting", "reason": "Fabricated commitment", "severity": "critical", "patterns": ["guaranteed approval", "you''re approved", "i guarantee", "guaranteed rate"]}, {"text": "Claiming the policy is free, paid for by the VA, or a refund of taxes", "reason": "False product claim", "severity": "critical", "patterns": ["it''s free", "the va pays", "paid for by the government", "no cost to you"]}, {"text": "Stating that the offer expires tonight or rates rise tomorrow", "reason": "Coercive pressure", "severity": "major", "patterns": ["expires tonight", "rates go up tomorrow", "last chance"]}]}', 2, true),
  ('inbound-switch-callback', '"Inbound Switch — Protection Request Callback"', '{"difficulty": 1, "segment": "Inbound · returned request", "skills": ["fact find", "rate positioning", "closing"], "estimatedMinutes": 6, "maxDurationSec": 720, "goal": "Return the prospect''s protection request, complete the fact find, present two options and lock in coverage.", "agentGoal": "complete the fact find and get agreement on one of two options today", "prospectGoal": "understand what she requested, get a fair rate, and not be rushed", "winCondition": "Fact find complete and the prospect chooses an option and agrees to set up the draft.", "difficultyPolicy": "Introductory: the prospect is warm because she requested the call; objections are mild and resolve after one relevant response.", "earlyEndConditions": ["Prospect ends the call if bank details are requested before the fact find is complete."], "allowedReferenceMaterial": ["Inbound Switch — Open / Fact Find / Close"], "gradedSummary": ["Fact-find completeness", "Two-option close", "Accuracy"], "openingLine": "Hi — yes, I did fill something out online. What is this about exactly?"}', '{"name": "Denise Carter", "role": "Widow, 64, part-time school office clerk", "companyProfile": "Lives alone in Tucson; her daughter Maya is her only family", "situation": "Filled out an online form for burial coverage after her husband''s funeral cost more than expected.", "currentSolution": "No coverage; her husband''s policy paid out and is gone.", "businessPressure": "Wants Maya never to face what she faced.", "decisionProcess": "Decides alone but dislikes being rushed; wants to understand the options.", "knowledgeLevel": "Understands why she needs coverage; does not understand carriers, ratings, or how premiums are set.", "speakingStyle": "Warm, talkative, asks practical questions, apologizes when she interrupts.", "hiddenPriorities": ["A payment she can keep for life", "A carrier she can trust"], "hardConstraints": ["Will not give bank details before the fact find is complete"], "age": 64, "voice": {"provider": "elevenlabs", "voiceId": "EXAVITQu4vr4xnSDxMaL", "label": "Sarah — warm American female", "pitchHint": "mid"}}', '[{"id": "think_about_it", "key": "think_about_it", "required": true, "title": "I need to think about it", "data": {"difficulty": 1, "intent": "Generic stall with no specific concern named.", "underlyingConcern": "An unspoken concern (price, trust, or carrier) that the prospect has not articulated; wants time to consult or to end the call politely.", "canonicalForms": ["Let me think about it.", "I''m not going to decide today.", "Call me back next week."], "variations": ["I want to sleep on it.", "I don''t like making decisions on the phone."], "triggers": {"afterPhase": "close", "minAgentTurns": 5}, "responsePrinciples": ["Isolate the real concern: price, coverage amount, or carrier.", "Explain the cost of waiting in factual terms (age-banded rates, health changes).", "Do not pressure; make deciding now easier than deciding later."], "disallowedClaims": ["Rates go up tomorrow", "This offer expires tonight"], "evidenceRefs": ["library:Objection — I need to think about it"], "resolutionChecks": ["The specific concern is named by the prospect.", "Agent addresses that concern and re-asks for the decision."], "followUps": {"ifWeak": ["I just need time, that''s all."], "ifStrong": ["I guess it''s mostly the price I''m unsure about."]}, "example": "Of course — this is your family''s protection, not a small decision. Help me understand what specifically you need to think about — the price, the coverage amount, or the carrier?\n\nBecause whatever it is, I''d rather we figure it out together right now than have you sit on it for a month while your rate goes up.", "category": "timing_priority"}}, {"id": "price_cant_afford", "key": "price_cant_afford", "required": true, "title": "I can''t afford it", "data": {"difficulty": 2, "intent": "Prospect frames the monthly premium as unaffordable on a fixed income.", "underlyingConcern": "Fear of a payment that competes with rent, medication or groceries; wants the agent to right-size instead of upsell.", "canonicalForms": ["I can''t afford that right now.", "That''s too much money every month.", "I''m on a fixed income, I can''t add a bill."], "variations": ["Money is tight, I don''t know about adding another payment.", "My Social Security check doesn''t stretch that far.", "That''s more than I was thinking."], "triggers": {"afterPhase": "positioning", "minAgentTurns": 4, "keywords": ["month", "premium", "$", "dollars", "per month"]}, "responsePrinciples": ["Acknowledge the budget concern without retreating from the need.", "Re-anchor on what happens to the family with no coverage.", "Right-size the premium to the stated comfort level; the coverage can increase later.", "Offer two concrete price points instead of an open question."], "disallowedClaims": ["Rates are locked forever regardless of carrier", "The plan is free or paid for by the VA", "Approval is guaranteed"], "evidenceRefs": ["script:IF PRICE TOO HIGH", "library:Objection — I can''t afford it"], "resolutionChecks": ["Prospect names or accepts a monthly amount.", "Agent confirms the amount is comfortable before moving on."], "followUps": {"ifWeak": ["I hear you, but I still don''t see where the money comes from.", "Can you just send me something in the mail?"], "ifStrong": ["Fifty a month I could probably do.", "If it''s around that, okay."]}, "example": "I hear you — I''m not here to put you in something you can''t afford. That''s why I asked about your budget upfront.\n\nQuestion though: what happens to your family if something happens to you and there''s NO coverage? That''s the real ''can''t afford it.''\n\nLet''s start at the level you''re comfortable with — we can always increase later. What works — $50/mo or $100/mo?", "category": "price_budget"}}, {"id": "existing_coverage", "key": "existing_coverage", "required": false, "title": "I already have coverage", "data": {"difficulty": 2, "intent": "Prospect believes an existing policy or the VA burial benefit already covers the need.", "underlyingConcern": "Does not want to duplicate a cost; may not know what the existing coverage actually pays or whether it is term coverage that will expire.", "canonicalForms": ["I already have life insurance.", "The VA covers my burial.", "I have something through my old job."], "variations": ["My wife has a policy on me already.", "Don''t veterans get a burial paid for?"], "triggers": {"afterPhase": "discovery", "minAgentTurns": 3, "keywords": ["coverage", "policy", "burial"]}, "responsePrinciples": ["Ask what the existing coverage pays and when it ends.", "Explain the difference between a term policy, a work policy that ends at retirement, and permanent final-expense coverage.", "Position the new coverage as filling the gap, not replacing what works."], "disallowedClaims": ["The VA pays nothing toward burial", "Your existing policy is worthless"], "evidenceRefs": ["script:TERM CONVERSION PITCH", "script:FINAL EXPENSE INFLATION PITCH"], "resolutionChecks": ["Prospect states what the existing coverage pays.", "Agent quantifies the gap and the prospect acknowledges it."], "followUps": {"ifWeak": ["I think it''s enough, honestly."], "ifStrong": ["I''m not sure how much it pays, to be honest."]}, "example": "That''s good — let''s make sure it does what you think. Is that a term policy or something that lasts your whole life, and do you know the amount? Most work policies end at retirement, and the VA burial allowance is a partial reimbursement, not a payout.", "category": "need_status_quo"}}]', '{"dimensions": [{"id": "discovery", "label": "Discovery and diagnosis", "points": 15, "description": "Relevant questions, depth, sequencing, and use of answers.", "excellent": "Asks who the coverage is for and why, uncovers the budget and health picture, and uses each answer in the next question."}, {"id": "objection_recognition", "label": "Objection recognition", "points": 10, "description": "Identifies the real concern rather than answering the surface phrase.", "excellent": "Names the concern under the words (''it sounds like the worry is the monthly bill, not the coverage'') before responding."}, {"id": "acknowledge_clarify", "label": "Acknowledge and clarify", "points": 15, "description": "Validates without capitulating; asks focused clarifying questions.", "excellent": "One sentence of acknowledgement, then a specific clarifying question, then silence."}, {"id": "response_accuracy", "label": "Response relevance and accuracy", "points": 15, "description": "Direct, tailored, script- and claim-grounded response without fabrication.", "excellent": "Uses only approved facts, ties the response to what the prospect said, and never invents a rate or guarantee."}, {"id": "resolution_advancement", "label": "Resolution and advancement", "points": 15, "description": "Checks resolution, earns commitment, and advances to a credible next step.", "excellent": "Asks ''does that take care of it?'', hears a yes, and moves to the concrete next step."}, {"id": "listening_control", "label": "Listening and call control", "points": 10, "description": "Turn balance, interruptions, concise transitions, agenda and time control.", "excellent": "Lets the prospect finish, keeps turns short, and steers back to the agenda without talking over them."}, {"id": "value_articulation", "label": "Value articulation", "points": 10, "description": "Connects value to stated priorities with appropriate proof.", "excellent": "Repeats the prospect''s own reason back and attaches the coverage to it."}, {"id": "delivery", "label": "Delivery and tonality", "points": 5, "description": "Observable pace, clarity, fillers, pauses, and volume consistency.", "excellent": "Steady pace inside the benchmark, few fillers, deliberate pauses after questions."}, {"id": "compliance", "label": "Compliance and professionalism", "points": 5, "description": "Required disclosures, approved claims, respectful conduct, data handling.", "excellent": "States identity and licensing plainly, never implies VA or government affiliation, handles bank details only after consent."}], "objectionStages": {"acknowledge": 15, "clarify": 20, "isolate": 15, "respond": 25, "proof": 10, "confirm": 15}, "passRules": {"overallMin": 80, "requiredObjectionMin": 70, "complianceMin": 4, "complianceCriterionId": "compliance", "evidenceCoverageMin": 0.6}, "criticalFailureRules": [{"id": "fabricated_fact", "label": "Fabricated price, guarantee, legal term, or capability", "description": "Any specific rate, guarantee, approval promise, legal term or carrier capability not present in approved knowledge."}, {"id": "government_affiliation", "label": "Implied VA or government affiliation", "description": "Stating or implying the call is from the VA, the military, or a government program."}, {"id": "prohibited_language", "label": "Prohibited, discriminatory, coercive or abusive language", "description": "Threats, slurs, or coercion of any kind."}, {"id": "missing_disclosure", "label": "Missing mandatory disclosure", "description": "Bank or payment details requested before identity, agency and licensing were stated."}, {"id": "sensitive_data", "label": "Mishandling sensitive data", "description": "Reading back or repeating full bank, Social Security or card numbers aloud."}, {"id": "unauthorized_commitment", "label": "Unapproved commitment on behalf of the company", "description": "Promising refunds, rate holds or approvals the agency cannot make."}], "deliveryBenchmarks": {"wordsPerMinute": [130, 175], "fillersPerMinute": 4, "longestMonologueSec": 45, "talkRatioAgent": [0.4, 0.6], "responseLatencyMs": [300, 1800]}}', '{"approved": [{"text": "Coverage is written by an A-rated carrier and the rate is set by your age and health at the time you apply.", "category": "pricing", "source": "script:DEEP DIVE"}, {"text": "Once the policy is in force, the premium does not increase and the coverage does not decrease.", "category": "product", "source": "script:FINAL EXPENSE INFLATION PITCH"}, {"text": "There is a free-look period after the policy is issued during which it can be cancelled for a full refund (30 days is the figure in the agency library; state minimums vary).", "category": "terms", "source": "library:Objection — I need to talk to my spouse"}, {"text": "The agent is a licensed life insurance agent with the agency; the agency is not the VA and does not represent any government program.", "category": "identity", "source": "brand:Apex Standard"}, {"text": "Coverage can start at a lower amount and be increased later, subject to underwriting.", "category": "product", "source": "library:Objection — I can''t afford it"}, {"text": "The beneficiary receives the death benefit directly and can use it for any purpose, including burial costs.", "category": "product", "source": "script:BENEFICIARY"}], "prohibited": [{"text": "Implying the call is from the VA, the military, or a government program", "reason": "Deceptive; also a compliance violation", "severity": "critical", "patterns": ["calling from the va", "this is the va", "government program", "government benefit", "military benefit", "with the va", "va benefits office", "the va benefits", "government burial benefit", "your government benefit", "from the veterans administration"]}, {"text": "Guaranteeing approval or a specific rate before underwriting", "reason": "Fabricated commitment", "severity": "critical", "patterns": ["guaranteed approval", "you''re approved", "i guarantee", "guaranteed rate"]}, {"text": "Claiming the policy is free, paid for by the VA, or a refund of taxes", "reason": "False product claim", "severity": "critical", "patterns": ["it''s free", "the va pays", "paid for by the government", "no cost to you"]}, {"text": "Stating that the offer expires tonight or rates rise tomorrow", "reason": "Coercive pressure", "severity": "major", "patterns": ["expires tonight", "rates go up tomorrow", "last chance"]}]}', 1, true),
  ('vet-fe-hard', '"Veteran Final Expense — Hard Mode"', '{"difficulty": 3, "segment": "Final expense · veterans", "skills": ["objection handling", "call control", "compliance"], "estimatedMinutes": 10, "maxDurationSec": 1080, "goal": "Same verification call with a skeptical, interrupting prospect who raises every objection in the library.", "agentGoal": "keep control, resolve every objection accurately and earn a commitment", "prospectGoal": "get off the phone unless the agent proves legitimacy and real value", "winCondition": "All required objections resolved and a specific next step agreed.", "difficultyPolicy": "Hard: the prospect interrupts long monologues, gives one-word answers until rapport is earned, re-raises an objection that was answered without a check-in, and probes any unsupported claim.", "earlyEndConditions": ["Prospect hangs up on any implied government affiliation.", "Prospect hangs up after two unsupported claims."], "allowedReferenceMaterial": ["Veteran Final Expense — Full Call Script", "Objection library"], "gradedSummary": ["All four required objections", "Call control under interruption", "Zero fabricated claims"], "openingLine": "Yeah? Make it quick, I''m in the middle of something."}', '{"name": "Walter Reyes", "role": "Retired Army staff sergeant, 71", "companyProfile": "Household of two on Social Security and a small Army pension in Mesa, Arizona", "situation": "Received several ''veteran benefits'' calls this year and hung up on most of them; his wife Linda handles the bills.", "currentSolution": "A $10,000 group policy from a former employer that he believes is still active; unsure whether it ended at retirement.", "businessPressure": "Fixed income; a recent hospital bill for Linda made him aware of what costs land on the family.", "decisionProcess": "Decides jointly with Linda; will not give bank details on a first call unless the caller is clearly legitimate.", "knowledgeLevel": "Knows the VA burial allowance exists but not what it pays; does not know term vs whole life.", "speakingStyle": "Short sentences, dry humor, suspicious at first, warms up when treated straight; says ''go ahead'' when convinced.", "hiddenPriorities": ["Not leaving Linda with a bill", "Not being fooled", "Keeping the payment under about $60 a month"], "hardConstraints": ["Will not proceed if the caller implies the VA or government is involved", "Will not give bank details before identity and licensing are stated"], "age": 71, "voice": {"provider": "elevenlabs", "voiceId": "pqHfZKP75CvOlQylNhV4", "label": "Bill — older American male", "pitchHint": "low"}}', '[{"id": "trust_scam", "key": "trust_scam", "required": true, "title": "How do I know this isn''t a scam?", "data": {"difficulty": 2, "intent": "Prospect questions the caller''s legitimacy and the authority behind the call.", "underlyingConcern": "Has received fraudulent ''benefits'' calls before; needs verifiable identity and a reason to keep listening.", "canonicalForms": ["How do I know you''re legitimate?", "I get scam calls every day.", "Who are you with again?"], "variations": ["My son told me never to give information over the phone.", "Is this the VA calling?"], "triggers": {"afterPhase": "open", "minAgentTurns": 1, "keywords": ["verify", "benefits", "coordinator"]}, "responsePrinciples": ["State the agency name, the agent''s name and license status plainly.", "Never imply government or VA affiliation.", "Offer a verifiable step (callback number, carrier name, written confirmation) and keep the call moving."], "disallowedClaims": ["We are calling from the VA", "This is a government program", "You were selected by the military"], "evidenceRefs": ["script:GAIN CREDENTIALS", "brand:Apex Standard"], "resolutionChecks": ["Prospect accepts the identity explanation and continues answering questions."], "followUps": {"ifWeak": ["That doesn''t tell me anything. Which company?"], "ifStrong": ["Alright, go ahead then."]}, "example": "I''m a licensed life insurance agent with the agency, not the VA — the VA doesn''t call about this. Here''s my license number and a callback line; the coverage itself is written by an A-rated carrier.", "category": "trust_risk"}}, {"id": "existing_coverage", "key": "existing_coverage", "required": true, "title": "I already have coverage", "data": {"difficulty": 2, "intent": "Prospect believes an existing policy or the VA burial benefit already covers the need.", "underlyingConcern": "Does not want to duplicate a cost; may not know what the existing coverage actually pays or whether it is term coverage that will expire.", "canonicalForms": ["I already have life insurance.", "The VA covers my burial.", "I have something through my old job."], "variations": ["My wife has a policy on me already.", "Don''t veterans get a burial paid for?"], "triggers": {"afterPhase": "discovery", "minAgentTurns": 3, "keywords": ["coverage", "policy", "burial"]}, "responsePrinciples": ["Ask what the existing coverage pays and when it ends.", "Explain the difference between a term policy, a work policy that ends at retirement, and permanent final-expense coverage.", "Position the new coverage as filling the gap, not replacing what works."], "disallowedClaims": ["The VA pays nothing toward burial", "Your existing policy is worthless"], "evidenceRefs": ["script:TERM CONVERSION PITCH", "script:FINAL EXPENSE INFLATION PITCH"], "resolutionChecks": ["Prospect states what the existing coverage pays.", "Agent quantifies the gap and the prospect acknowledges it."], "followUps": {"ifWeak": ["I think it''s enough, honestly."], "ifStrong": ["I''m not sure how much it pays, to be honest."]}, "example": "That''s good — let''s make sure it does what you think. Is that a term policy or something that lasts your whole life, and do you know the amount? Most work policies end at retirement, and the VA burial allowance is a partial reimbursement, not a payout.", "category": "need_status_quo"}}, {"id": "price_cant_afford", "key": "price_cant_afford", "required": true, "title": "I can''t afford it", "data": {"difficulty": 2, "intent": "Prospect frames the monthly premium as unaffordable on a fixed income.", "underlyingConcern": "Fear of a payment that competes with rent, medication or groceries; wants the agent to right-size instead of upsell.", "canonicalForms": ["I can''t afford that right now.", "That''s too much money every month.", "I''m on a fixed income, I can''t add a bill."], "variations": ["Money is tight, I don''t know about adding another payment.", "My Social Security check doesn''t stretch that far.", "That''s more than I was thinking."], "triggers": {"afterPhase": "positioning", "minAgentTurns": 4, "keywords": ["month", "premium", "$", "dollars", "per month"]}, "responsePrinciples": ["Acknowledge the budget concern without retreating from the need.", "Re-anchor on what happens to the family with no coverage.", "Right-size the premium to the stated comfort level; the coverage can increase later.", "Offer two concrete price points instead of an open question."], "disallowedClaims": ["Rates are locked forever regardless of carrier", "The plan is free or paid for by the VA", "Approval is guaranteed"], "evidenceRefs": ["script:IF PRICE TOO HIGH", "library:Objection — I can''t afford it"], "resolutionChecks": ["Prospect names or accepts a monthly amount.", "Agent confirms the amount is comfortable before moving on."], "followUps": {"ifWeak": ["I hear you, but I still don''t see where the money comes from.", "Can you just send me something in the mail?"], "ifStrong": ["Fifty a month I could probably do.", "If it''s around that, okay."]}, "example": "I hear you — I''m not here to put you in something you can''t afford. That''s why I asked about your budget upfront.\n\nQuestion though: what happens to your family if something happens to you and there''s NO coverage? That''s the real ''can''t afford it.''\n\nLet''s start at the level you''re comfortable with — we can always increase later. What works — $50/mo or $100/mo?", "category": "price_budget"}}, {"id": "spouse_decision", "key": "spouse_decision", "required": true, "title": "I need to talk to my spouse", "data": {"difficulty": 2, "intent": "Prospect defers the decision to a spouse who is not on the call.", "underlyingConcern": "Does not want to commit to a household expense alone; may also be using the spouse as a polite exit.", "canonicalForms": ["I need to talk to my wife first.", "My husband handles this kind of thing.", "I can''t decide without my spouse."], "variations": ["Let me run it by Linda and call you back.", "We make these decisions together."], "triggers": {"afterPhase": "close", "minAgentTurns": 6, "keywords": ["lock in", "set up", "bank", "draft", "today"]}, "responsePrinciples": ["Validate that the decision affects the spouse.", "Ask what the spouse would say about leaving the family unprotected.", "Offer to include the spouse now or lock the rate with the free-look period as the safety net.", "Confirm the plan and next step explicitly."], "disallowedClaims": ["The spouse cannot cancel", "There is no free-look or cancellation period"], "evidenceRefs": ["library:Objection — I need to talk to my spouse"], "resolutionChecks": ["Prospect agrees to proceed now, or a concrete joint call time is set with both parties.", "Agent states the free-look terms accurately."], "followUps": {"ifWeak": ["She''s going to say no, I already know it.", "Just mail me the paperwork."], "ifStrong": ["Well, if I can cancel within thirty days I suppose that''s fair.", "Let me grab her, she''s in the kitchen."]}, "example": "I totally get that — this IS a decision that affects them. Quick question: if you came home tonight and said you DIDN''T protect them, what do you think they''d say?\n\nLet''s do this: I''ll lock in the rate at today''s health, you have 30 days to cancel for any reason — including if your spouse says no — and you''ll have peace of mind tonight knowing it''s done. Sound fair?", "category": "authority_decision"}}, {"id": "think_about_it", "key": "think_about_it", "required": false, "title": "I need to think about it", "data": {"difficulty": 1, "intent": "Generic stall with no specific concern named.", "underlyingConcern": "An unspoken concern (price, trust, or carrier) that the prospect has not articulated; wants time to consult or to end the call politely.", "canonicalForms": ["Let me think about it.", "I''m not going to decide today.", "Call me back next week."], "variations": ["I want to sleep on it.", "I don''t like making decisions on the phone."], "triggers": {"afterPhase": "close", "minAgentTurns": 5}, "responsePrinciples": ["Isolate the real concern: price, coverage amount, or carrier.", "Explain the cost of waiting in factual terms (age-banded rates, health changes).", "Do not pressure; make deciding now easier than deciding later."], "disallowedClaims": ["Rates go up tomorrow", "This offer expires tonight"], "evidenceRefs": ["library:Objection — I need to think about it"], "resolutionChecks": ["The specific concern is named by the prospect.", "Agent addresses that concern and re-asks for the decision."], "followUps": {"ifWeak": ["I just need time, that''s all."], "ifStrong": ["I guess it''s mostly the price I''m unsure about."]}, "example": "Of course — this is your family''s protection, not a small decision. Help me understand what specifically you need to think about — the price, the coverage amount, or the carrier?\n\nBecause whatever it is, I''d rather we figure it out together right now than have you sit on it for a month while your rate goes up.", "category": "timing_priority"}}, {"id": "healthy_not_now", "key": "healthy_not_now", "required": false, "title": "I''m healthy, I don''t need this now", "data": {"difficulty": 3, "intent": "Prospect sees no urgency because of current good health.", "underlyingConcern": "Discomfort with mortality; wants a reason grounded in facts rather than fear.", "canonicalForms": ["I''m in great shape, this can wait.", "I''ll deal with it when I''m older.", "Nobody in my family goes early."], "variations": ["My doctor says I''m fine.", "I''m not planning on going anywhere."], "triggers": {"afterPhase": "positioning", "minAgentTurns": 4, "keywords": ["health", "qualify", "rate"]}, "responsePrinciples": ["Agree that good health is exactly why now is the right time (rates are set at today''s age and health).", "Use factual age-banded pricing, not fear.", "Tie back to the beneficiary the prospect named earlier."], "disallowedClaims": ["You will not qualify later", "Guaranteed acceptance at any age"], "evidenceRefs": ["script:DEEP DIVE", "script:IF THEY HESITATE"], "resolutionChecks": ["Prospect accepts that locking today''s health class is the reason to act now."], "followUps": {"ifWeak": ["I hear that from every salesman."], "ifStrong": ["I suppose it''s cheaper now than later."]}, "example": "That''s exactly why we''re talking now — the rate is set by your age and health today, and it never goes up. If we wait until something changes, the same coverage costs more or isn''t available. And you told me Linda would be the one handling everything.", "category": "timing_priority"}}]', '{"dimensions": [{"id": "discovery", "label": "Discovery and diagnosis", "points": 15, "description": "Relevant questions, depth, sequencing, and use of answers.", "excellent": "Asks who the coverage is for and why, uncovers the budget and health picture, and uses each answer in the next question."}, {"id": "objection_recognition", "label": "Objection recognition", "points": 10, "description": "Identifies the real concern rather than answering the surface phrase.", "excellent": "Names the concern under the words (''it sounds like the worry is the monthly bill, not the coverage'') before responding."}, {"id": "acknowledge_clarify", "label": "Acknowledge and clarify", "points": 15, "description": "Validates without capitulating; asks focused clarifying questions.", "excellent": "One sentence of acknowledgem