.6}, "criticalFailureRules": [{"id": "fabricated_fact", "label": "Fabricated price, guarantee, legal term, or capability", "description": "Any specific rate, guarantee, approval promise, legal term or carrier capability not present in approved knowledge."}, {"id": "government_affiliation", "label": "Implied VA or government affiliation", "description": "Stating or implying the call is from the VA, the military, or a government program."}, {"id": "prohibited_language", "label": "Prohibited, discriminatory, coercive or abusive language", "description": "Threats, slurs, or coercion of any kind."}, {"id": "missing_disclosure", "label": "Missing mandatory disclosure", "description": "Bank or payment details requested before identity, agency and licensing were stated."}, {"id": "sensitive_data", "label": "Mishandling sensitive data", "description": "Reading back or repeating full bank, Social Security or card numbers aloud."}, {"id": "unauthorized_commitment", "label": "Unapproved commitment on behalf of the company", "description": "Promising refunds, rate holds or approvals the agency cannot make."}], "deliveryBenchmarks": {"wordsPerMinute": [130, 175], "fillersPerMinute": 4, "longestMonologueSec": 45, "talkRatioAgent": [0.4, 0.6], "responseLatencyMs": [300, 1800]}}', '{"approved": [{"text": "Coverage is written by an A-rated carrier and the rate is set by your age and health at the time you apply.", "category": "pricing", "source": "script:DEEP DIVE"}, {"text": "Once the policy is in force, the premium does not increase and the coverage does not decrease.", "category": "product", "source": "script:FINAL EXPENSE INFLATION PITCH"}, {"text": "There is a free-look period after the policy is issued during which it can be cancelled for a full refund (30 days is the figure in the agency library; state minimums vary).", "category": "terms", "source": "library:Objection — I need to talk to my spouse"}, {"text": "The agent is a licensed life insurance agent with the agency; the agency is not the VA and does not represent any government program.", "category": "identity", "source": "brand:Apex Standard"}, {"text": "Coverage can start at a lower amount and be increased later, subject to underwriting.", "category": "product", "source": "library:Objection — I can''t afford it"}, {"text": "The beneficiary receives the death benefit directly and can use it for any purpose, including burial costs.", "category": "product", "source": "script:BENEFICIARY"}], "prohibited": [{"text": "Implying the call is from the VA, the military, or a government program", "reason": "Deceptive; also a compliance violation", "severity": "critical", "patterns": ["calling from the va", "this is the va", "government program", "government benefit", "military benefit", "with the va", "va benefits office", "the va benefits", "government burial benefit", "your government benefit", "from the veterans administration"]}, {"text": "Guaranteeing approval or a specific rate before underwriting", "reason": "Fabricated commitment", "severity": "critical", "patterns": ["guaranteed approval", "you''re approved", "i guarantee", "guaranteed rate"]}, {"text": "Claiming the policy is free, paid for by the VA, or a refund of taxes", "reason": "False product claim", "severity": "critical", "patterns": ["it''s free", "the va pays", "paid for by the government", "no cost to you"]}, {"text": "Stating that the offer expires tonight or rates rise tomorrow", "reason": "Coercive pressure", "severity": "major", "patterns": ["expires tonight", "rates go up tomorrow", "last chance"]}]}', 3, true)
on conflict (id) do update set title = excluded.title, data = excluded.data, persona = excluded.persona, objections = excluded.objections, rubric = excluded.rubric, claims = excluded.claims, difficulty = excluded.difficulty, updated_at = now();
